/**
 * Todo Roadmap — the developer backlog (todo.txt) turned into a fifth IT
 * Development board. Unlike CLM/Nonprofit/Platform Readiness/Production
 * Tools, these 20 items are unrelated to each other, so each section carries
 * exactly one task (one PR) instead of a multi-task batch. Ordered by
 * estimated effort, smallest first, so the board reads as a prioritized
 * queue rather than a random list.
 *
 * PR convention: one PR per section. Title `TODO {code} {title}`. Branch
 * `cursor/todo/{section}-{code}-*`. Body: Who, What, Where, Why, When, How,
 * and Done when, generated by todo-pr-body.ts from this file — do not
 * hand-author PR descriptions, edit the task below and regenerate.
 */

import type { RoadmapCatalogSection } from "../types";

/**
 * Draft stub PRs opened on cursor/todo/{section}-{code}-* so each section
 * shows a real linked PR instead of "No catalog PRs linked to this section".
 * Each is a one-line ticket marker; merging the real implementation on that
 * same branch is what actually completes the task.
 */
const TODO_STUB_PR_NUMBERS: Record<number, number> = {
	1: 303,
	2: 304,
	3: 305,
	4: 306,
	5: 307,
	6: 308,
	7: 309,
	8: 310,
	9: 311,
	10: 312,
	11: 313,
	12: 314,
	13: 315,
	14: 316,
	15: 317,
	16: 318,
	17: 319,
	18: 320,
	19: 321,
	20: 322,
};

function spec(
	who: string,
	what: string,
	where: string,
	why: string,
	when: string,
	how: string,
): string {
	return `Who: ${who}. What: ${what}. Where: ${where}. Why: ${why}. When: ${when}. How: ${how}.`;
}

function t(
	sectionNumber: number,
	title: string,
	description: string,
	acceptanceCriteria: string[],
): RoadmapCatalogSection {
	const taskCode = `${sectionNumber}.1`;
	const stubPrNumber = TODO_STUB_PR_NUMBERS[sectionNumber];
	return {
		sectionNumber,
		title,
		sourceRef: "todo.txt",
		// Shows the stub PR in the section's PR pane (catalog-query.ts reads
		// this array, not the task's linkedPrNumber, for that list). The real
		// implementation lands as more commits on this same draft PR/branch —
		// merging it with green CI is what completes the task (default rule).
		linkedPrNumbers: stubPrNumber != null ? [stubPrNumber] : undefined,
		tasks: [
			{
				taskCode,
				title,
				description,
				acceptanceCriteria,
				testSuiteRef: `tests/roadmap/todo/${taskCode.replace(/\./g, "-")}.test.ts`,
				linkedPrNumber: stubPrNumber,
			},
		],
	};
}

